typedef float rational_t;
#define NULL 0

class vector3d
{
public:
  rational_t x, y, z;
};

class sphere
{
public:
  sphere(const vector3d& _origin,rational_t _r) : center(_origin), radius(_r) {}
  rational_t get_r() const { return radius; }
  void set_r(rational_t r) { radius=r; }
private:
  vector3d center;
  rational_t radius;
};

class stringx {};
template<class T> class less {};
class region;
class portal;

template<class _NodeKey, class _NodeData, class _EdgeData, class _KeyComp>
class graph
{
public:
  class node;
  class edge
  {
    _EdgeData data;
    node* dest;
  public:
    _EdgeData& get_data() { return data; }
  };
  class node
  {
    struct link { link* next; link* prev; };
  public:
    class iterator
    {
      link* p;
    public:
      iterator() {}
      iterator(link* q) : p(q) {}
      bool operator!=(const iterator& b) const { return p != b.p; }
      iterator& operator++() { p = p->next; return *this; }
      edge& operator*() const { return *(edge*)(p + 1); }
    };
    link* sentinel;
    iterator begin() { return iterator(sentinel->next); }
    iterator end() { return iterator(sentinel); }
  };
};

typedef graph<stringx, region*, portal*, less<stringx> > region_graph;
typedef region_graph::node region_node;
typedef region_node::iterator edge_iterator;

class terrain;
class entity
{
  char pad[404];
  unsigned int ext_flags;
public:
  virtual rational_t get_radius() const;
  virtual void compute_sector(terrain& ter, bool use_high_res_intersect = false);
  void set_needs_compute_sector(bool a)
  {
    if(a) ext_flags|=0x20000000; else ext_flags&=~0x20000000;
  }
};

class portal
{
public:
  bool touches_sphere(const sphere& s) const;
  bool touches_segment(const vector3d& p1, const vector3d& p2) const;
};

class world_dynamics_system
{
  char pad[236];
  terrain* the_terrain;
public:
  terrain& get_the_terrain() { return *the_terrain; }
};

extern world_dynamics_system* g_world_ptr;

class ai_locomotion
{
public:
  entity* get_my_entity() const;
  void conditional_compute_sector(region_node *rgn, const vector3d &p1, const vector3d &p2);
};

void ai_locomotion::conditional_compute_sector(region_node *rgn, const vector3d &p1, const vector3d &p2)
{
  get_my_entity()->set_needs_compute_sector(false);
  // check for intersection with portals leading from this region
  if(rgn != NULL)
  {
    sphere me_sphere( p1, get_my_entity()->get_radius() );
    if(me_sphere.get_r() < 1.0f)
      me_sphere.set_r(1.0f);

    edge_iterator tei = rgn->begin();
    edge_iterator tei_end = rgn->end();
    for ( ; tei!=tei_end; ++tei )
    {
      portal* port = (*tei).get_data();
      if ( port )
      {
        if (port->touches_sphere(me_sphere) || port->touches_segment(p1, p2))
        {
          get_my_entity()->compute_sector( g_world_ptr->get_the_terrain() );
          return;
        }
      }
/*
      region_node* dest = (*tei).get_dest();
      portal* port = (*tei).get_data();
      if ( dest && port && port->is_active() )
      {
        region* dr = dest->get_data();
        // don't bother with inactive regions or those we've already visited
        if ( dr && dr->is_active() && (port->touches_sphere(me_sphere) || port->touches_segment(p1, p2)))
        {
          get_my_entity()->compute_sector( g_world_ptr->get_the_terrain() );
          return;
        }
      }
*/
    }
  }
  else
    get_my_entity()->compute_sector( g_world_ptr->get_the_terrain() );
}
